import{_ as i,r as s,o as c,c as r,e as o,a as e,s as t,d as n}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Components - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Introduction","slug":"introduction","link":"#introduction","children":[]},{"level":2,"title":"Components aliases","slug":"components-aliases","link":"#components-aliases","children":[]},{"level":2,"title":"Using external property values","slug":"using-external-property-values","link":"#using-external-property-values","children":[]},{"level":2,"title":"Passing variables to components","slug":"passing-variables-to-components","link":"#passing-variables-to-components","children":[]},{"level":2,"title":"Customizing default markup","slug":"customizing-default-markup","link":"#customizing-default-markup","children":[{"level":3,"title":"Moving default markup to a partial","slug":"moving-default-markup-to-a-partial","link":"#moving-default-markup-to-a-partial","children":[]},{"level":3,"title":"Overriding component partials","slug":"overriding-component-partials","link":"#overriding-component-partials","children":[]}]},{"level":2,"title":"The \\"View Bag\\" component","slug":"the-view-bag-component","link":"#the-view-bag-component","children":[]},{"level":2,"title":"Soft components","slug":"soft-components","link":"#soft-components","children":[]}],"relativePath":"1.x/cms/components.md","filePath":"1.x/cms/components.md"}'),u={name:"1.x/cms/components.md"};function d(m,a,g,h,k,v){const p=s("pre-heading"),l=s("post-heading");return c(),r("div",null,[o(p),a[0]||(a[0]=e("h1",null,"Components",-1)),o(l),a[1]||(a[1]=t(`<p>Components are configurable building elements that can be attached to any page, partial or layout. Components are key features of October. Each component implements some functionality that extends your website. Components can output HTML markup on a page, but it is not necessary - other important features of components are handling <a href="./../ajax/introduction.html">AJAX requests</a>, handling form postbacks and handling the page execution cycle, that allows to inject variables to pages or implement the website security.</p><p>This article describes the components basics and doesn&#39;t explain how to use <a href="./../ajax/handlers.html">components with AJAX</a> or <a href="./../plugin/components.html">developing components</a> as part of plugins.</p><blockquote><p><strong>Note:</strong> Using components inside partials has limited functionality, this is described in more detail in the <a href="./partials.html#dynamic-partials">dynamic partials</a> article.</p></blockquote><h2 id="introduction"><a href="#introduction" class="header-anchor">#</a> Introduction</h2><p>If you use the back-end user interface you can add components to your pages, partials and layouts by clicking the component in the Components panel. If you use a text editor you can attach a component to a page or layout by adding its name to the <a href="./themes.html#configuration-section">Configuration</a> section of the template file. The next example demonstrates how to add a demo To-do component to a page:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Components demonstration</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/components</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>This initializes the component with the properties that are defined in the component section. Many components have properties, but it is not a requirement. Some properties are required, and some properties have default values. If you are not sure what properties are supported by a component, refer to the documentation provided by the developer, or use the Inspector in the October back-end. The Inspector opens when you click a component in the page or layout component panel.</p><p>When you refer a component, it automatically creates a page variable that matches the component name (<code>demoTodo</code> in the previous example). Components that provide HTML markup can be rendered on a page with the <code>{% component %}</code> tag, like this:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><blockquote><p><strong>Note:</strong> If two components with the same name are assigned to a page and layout together, the page component overrides any properties of the layout component.</p></blockquote><h2 id="components-aliases"><a href="#components-aliases" class="header-anchor">#</a> Components aliases</h2><p>If there are two plugins that register components with the same name, you can attach a component by using its fully qualified class name and assigning it an <em>alias</em>:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">October\\Demo\\Components\\Todo demoTodoAlias</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><p>The first parameter in the section is the class name, the second is the component alias name that will be used when attached to the page. If you specified a component alias you should use it everywhere in the page code when you refer to the component. Note that the next example refers to the component alias:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The aliases also allow you to define multiple components of the same class on a same page by using the short name first and an alias second. This lets you to use multiple instances of a same component on a page.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoA</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">10</span>
<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoB</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><h2 id="using-external-property-values"><a href="#using-external-property-values" class="header-anchor">#</a> Using external property values</h2><p>By default property values are initialized in the Configuration section where the component is defined, and the property values are static, like this:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div>`,20)),a[2]||(a[2]=e("div",null,[e("p",null,[n("However there is a way to initialize properties with values loaded from external parameters - URL parameters or "),e("a",{href:"./partials.html"},"partial"),n(" parameters (for components defined in partials). Use the "),e("code",{"v-pre":""},"{{ paramName }}"),n(" syntax for values that should be loaded from partial variables:")])],-1)),a[3]||(a[3]=t(`<div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>Assuming that in the example above the component <strong>demoTodo</strong> is defined in a partial, it will be initialized with a value loaded from the <strong>maxItems</strong> partial variable:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>my-todo-partial<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>10<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>You may use dot notation to retrieve a deeply nested value from an external parameter:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ data.maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div>`,5)),a[4]||(a[4]=e("div",null,[e("p",null,[n("To load a property value from the URL parameter, use the "),e("code",{"v-pre":""},"{{ :paramName }}"),n(" syntax, where the name starts with a colon ("),e("code",{"v-pre":""},":"),n("), for example:")])],-1)),a[5]||(a[5]=t(`<div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ :maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>The page, the component belongs to, should have a corresponding <a href="./pages.html#url-syntax">URL parameter</a> defined:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/todo/:maxItems</span>&quot;</span>
</code></pre></div><p>In the October back-end you can use the Inspector tool for assigning external values to component properties. In the Inspector you don&#39;t need to use the curly brackets to enter the parameter name. Each field in the Inspector has an icon on the right side, which opens the external parameter name editor. Enter the parameter name as <code>paramName</code> for partial variables or <code>:paramName</code> for URL parameters.</p><h2 id="passing-variables-to-components"><a href="#passing-variables-to-components" class="header-anchor">#</a> Passing variables to components</h2><p>Components can be designed to use variables at the time they are rendered, similar to <a href="./partials.html#passing-variables-to-partials">Partial variables</a>, they can be specified after the component name in the <code>{% component %}</code> tag. The specified variables will explicitly override the value of the <a href="./../plugin/components.html#component-properties">component properties</a>, including <a href="#using-external-property-values">external property values</a>.</p><p>In this example, the <strong>maxItems</strong> property of the component will be set to <em>7</em> at the time the component is rendered:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>7<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><blockquote><p><strong>Note</strong>: Not all components support passing variables when rendering.</p></blockquote><h2 id="customizing-default-markup"><a href="#customizing-default-markup" class="header-anchor">#</a> Customizing default markup</h2><p>The markup provided by components is generally intended as a usage example for the Component. In some cases you may wish to modify the appearance and output of a component. <a href="#moving-default-markup-to-a-partial">Moving the default markup to a theme partial</a> is suitable to completely overhaul a component. <a href="#overriding-component-partials">Overriding the component partials</a> is useful for cherry picking areas to customize.</p><h3 id="moving-default-markup-to-a-partial"><a href="#moving-default-markup-to-a-partial" class="header-anchor">#</a> Moving default markup to a partial</h3><p>Each component can have an entry point partial called <strong>default.htm</strong> that is rendered when the <code>{% component %}</code> tag is called, in the following example we will assume the component is called <strong>blogPost</strong>.</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;blog/post&quot;

[blogPost]
==
{% component &quot;blogPost&quot; %}
</code></pre></div><p>The output will be rendered from the plugin directory <strong>components/blogpost/default.htm</strong>. You can copy all the markup from this file and paste it directly in the page or to a new partial, called <strong>blog-post.htm</strong> for example.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Inside the markup you may notice references to a variable called <code>__SELF__</code>, this refers to the component object and should be replaced with the component alias used on the page, in this example it is <code>blogPost</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>This is the only change needed to allow the default component markup to work anywhere inside the theme. Now the component markup can be customized and rendered using the theme partial.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog-post.htm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>This process can be repeated for all other partials found in the component partial directory.</p><h3 id="overriding-component-partials"><a href="#overriding-component-partials" class="header-anchor">#</a> Overriding component partials</h3><p>All component partials can be overridden using the theme partials. If a component called <strong>channel</strong> uses the <strong>title.htm</strong> partial.</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;mypage&quot;

[channel]
==
{% component &quot;channel&quot; %}
</code></pre></div><p>We can override the partial by creating a file in our theme called <strong>partials/channel/title.htm</strong>.</p><p>The file path segments are broken down like this:</p><div class="table"><table tabindex="0"><thead><tr><th>Segment</th><th>Description</th></tr></thead><tbody><tr><td><strong>partials</strong></td><td>the theme partials directory</td></tr><tr><td><strong>channel</strong></td><td>the component alias (a partial subdirectory)</td></tr><tr><td><strong>title.htm</strong></td><td>the component partial to override</td></tr></tbody></table></div><p>The partial subdirectory name can be customized to anything by simply assigning the component an alias of the same name. For example, by assigning the <strong>channel</strong> component with a different alias <strong>foobar</strong> the override directory is also changed:</p><div class="language- extra-class"><pre class="language-text"><code>[channel foobar]
==
{% component &quot;foobar&quot; %}
</code></pre></div><p>Now we can override the <strong>title.htm</strong> partial by creating a file in our theme called <strong>partials/foobar/title.htm</strong>.</p><h2 id="the-view-bag-component"><a href="#the-view-bag-component" class="header-anchor">#</a> The &quot;View Bag&quot; component</h2><p>There is a special component included in October called <code>viewBag</code> that can be used on any page or layout. It allows ad hoc properties to be defined and accessed inside the markup area easily as variables. A good usage example is defining an active menu item inside a page:</p><div class="language- extra-class"><pre class="language-text"><code>title = &quot;About&quot;
url = &quot;/about.html&quot;
layout = &quot;default&quot;

[viewBag]
activeMenu = &quot;about&quot;
==

&lt;p&gt;Page content...&lt;/p&gt;
</code></pre></div><p>Any property defined for the component is then made available inside the page, layout, or partial markup using the <code>viewBag</code> variable. For example, in this layout the <strong>active</strong> class is added to the list item if the <code>viewBag.activeMenu</code> value is set to <strong>about</strong>:</p><div class="language- extra-class"><pre class="language-text"><code>description = &quot;Default layout&quot;
==
[...]

&lt;!-- Main navigation --&gt;
&lt;ul&gt;
    &lt;li class=&quot;{{ viewBag.activeMenu == &#39;about&#39; ? &#39;active&#39; }}&quot;&gt;About&lt;/li&gt;
    [...]
&lt;/ul&gt;
</code></pre></div><blockquote><p><strong>Note</strong>: The viewBag component is hidden on the back-end and is only available for file-based editing. It can also be used by other plugins to store data.</p></blockquote><h2 id="soft-components"><a href="#soft-components" class="header-anchor">#</a> Soft components</h2><p>Soft components are components in a theme that will continue to operate even if the linked component is no longer available. This allows theme and site developers to specify optional plugin components in their themes that will provide specific functionality if the plugin and/or component is present, while allowing the site to continue to function should the component no longer exist.</p><p>When soft components are present on a page and the component is unavailable, no output is generated for the component.</p><p>You can define soft components by prefixing the component name with an <code>@</code> symbol.</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;mypage&quot;

[@channel]
==
{% component &quot;channel&quot; %}
</code></pre></div><p>In this example, should the <code>channel</code> component not be available, the <code>{% component &quot;channel&quot; %}</code> tag will be ignored when the page is rendered.</p><p>Soft components also work with aliases as well:</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;mypage&quot;

[@channel channelSection]
==
{% component &quot;channelSection&quot; %}
</code></pre></div><p>As soft components do not contain any of the data that the component may provide normally if the component is not available, you must take care to ensure that any custom markup will gracefully handle any missing component information. For example:</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;mypage&quot;

[@channel]
==
{% if channel.name %}
    &lt;div class=&quot;channel&quot;&gt;
        {% channel.name %}
    &lt;/div&gt;
{% endif %}
</code></pre></div>`,46))])}const b=i(u,[["render",d]]);export{y as __pageData,b as default};
